interface Livro {
  id: number;
  titulo: string;
  isbn: string;
  paginas: number;
}

// As definições reais da biblioteca padrão, copiadas tal e qual
type MeuPick<T, K extends keyof T> = { [P in K]: T[P] };
type MeuOmit<T, K extends keyof any> = MeuPick<T, Exclude<keyof T, K>>;
type MeuRecord<K extends keyof any, T> = { [P in K]: T };

type Resumo = MeuPick<Livro, "id" | "titulo">;
const resumo: Resumo = { id: 1, titulo: "Os Maias" };
console.log(resumo.titulo); // Os Maias

type Publico = MeuOmit<Livro, "isbn">;
const publico: Publico = { id: 2, titulo: "Peregrinação", paginas: 480 };
console.log(publico.paginas); // 480

type PorIdioma = MeuRecord<"pt" | "en", string>;
const saudacao: PorIdioma = { pt: "Olá", en: "Hello" };
console.log(saudacao.pt); // Olá

// Os tipos da biblioteca aceitam exatamente os mesmos valores
const resumoLib: Pick<Livro, "id" | "titulo"> = resumo;
const publicoLib: Omit<Livro, "isbn"> = publico;
const saudacaoLib: Record<"pt" | "en", string> = saudacao;
console.log(resumoLib.id, publicoLib.titulo, saudacaoLib.en); // 1 Peregrinação Hello

interface Encomenda {
  readonly id: number;
  cliente: string;
  nota?: string;
  morada: string;
  total: number;
}

type LinhaDeLista = Pick<Encomenda, "id" | "cliente" | "nota">;

const linha: LinhaDeLista = { id: 10, cliente: "Ana" };
console.log(linha.cliente); // Ana
console.log(linha.nota); // undefined

function resumir(l: LinhaDeLista): string {
  return l.id + " - " + l.cliente + (l.nota ? " (" + l.nota + ")" : "");
}
console.log(resumir(linha)); // 10 - Ana
console.log(resumir({ id: 11, cliente: "Rui", nota: "urgente" })); // 11 - Rui (urgente)

// @ts-expect-error morada ficou de fora do Pick: a propriedade não existe
console.log(linha.morada);

// @ts-expect-error readonly viajou com a chave: id continua só de leitura
linha.id = 12;

// @ts-expect-error K extends keyof T rejeita uma chave que Encomenda não tem
type Invalida = Pick<Encomenda, "desconto">;

interface Conta {
  readonly id: number;
  email: string;
  telefone?: string;
  palavraPasse: string;
}

type ContaPublica = Omit<Conta, "palavraPasse">;

const publica: ContaPublica = { id: 1, email: "ana@exemplo.pt" };
console.log(publica.email); // ana@exemplo.pt

// @ts-expect-error palavraPasse deixou de existir neste tipo
console.log(publica.palavraPasse);

// @ts-expect-error readonly sobreviveu à passagem por Pick
publica.id = 2;

// O segundo parâmetro é keyof any: uma chave mal escrita passa em silêncio
type ContaEnganosa = Omit<Conta, "palavraPass">;

const enganosa: ContaEnganosa = {
  id: 3,
  email: "rui@exemplo.pt",
  palavraPasse: "segredo",
};
console.log(enganosa.palavraPasse); // segredo

interface Artigo {
  readonly id: number;
  titulo: string;
  corpo: string;
  rascunho: boolean;
}

// Uma linha: o mesmo Omit, mas com o constraint que a biblioteca não põe
type OmitEstrito<T, K extends keyof T> = Omit<T, K>;

type ArtigoPublicado = OmitEstrito<Artigo, "rascunho">;

const artigo: ArtigoPublicado = { id: 1, titulo: "Utility Types", corpo: "texto" };
console.log(artigo.titulo); // Utility Types

// @ts-expect-error o constraint apanha a chave mal escrita em compilação
type Errado = OmitEstrito<Artigo, "rascunhos">;

// A versão da biblioteca aceita a mesma chave mal escrita e não remove nada
type Silencioso = Omit<Artigo, "rascunhos">;
const aindaComRascunho: Silencioso = {
  id: 2,
  titulo: "Esboço",
  corpo: "texto",
  rascunho: true,
};
console.log(aindaComRascunho.rascunho); // true

type Estado = "pendente" | "enviada" | "entregue";

type Etiquetas = Record<Estado, string>;

const etiquetas: Etiquetas = {
  pendente: "À espera",
  enviada: "A caminho",
  entregue: "Entregue",
};
console.log(etiquetas.enviada); // A caminho

// @ts-expect-error faltar uma chave da união é erro: Record é exaustivo
const incompletas: Etiquetas = { pendente: "À espera", enviada: "A caminho" };
console.log(incompletas.pendente); // À espera

// Com string na posição das chaves nasce uma index signature
const contagens: Record<string, number> = { pendente: 2 };
const quantas = contagens.entregue;
console.log(quantas); // undefined, apesar de o tipo dizer number

// keyof any é string | number | symbol, por isso number também serve
const porIndice: Record<number, string> = { 0: "zero", 1: "um" };
console.log(porIndice[1]); // um

interface Utilizador {
  readonly id: string;
  nome: string;
  email: string;
  palavraPasse: string;
  criadoEm: string;
}

type FormularioRegisto = Pick<Utilizador, "nome" | "email" | "palavraPasse">;
type UtilizadorPublico = Omit<Utilizador, "palavraPasse">;
type IndicePorId = Record<string, UtilizadorPublico>;

function registar(
  form: FormularioRegisto,
  id: string,
  criadoEm: string
): UtilizadorPublico {
  return { id, nome: form.nome, email: form.email, criadoEm };
}

const indice: IndicePorId = {};
const criado = registar(
  { nome: "Ana", email: "ana@exemplo.pt", palavraPasse: "1234" },
  "u1",
  "2024-03-01"
);
indice[criado.id] = criado;

console.log(indice["u1"].nome); // Ana
console.log(Object.keys(indice).length); // 1

// @ts-expect-error o tipo público já não tem palavraPasse
console.log(indice["u1"].palavraPasse);

