interface Produto {
  readonly id: number;
  nome: string;
  preco: number;
  custoInterno: number;
  fornecedor: string;
}

type CartaoProduto = Pick<Produto, "id" | "nome" | "preco">;

const cartao: CartaoProduto = { id: 1, nome: "Teclado", preco: 49.9 };

function etiqueta(c: CartaoProduto): string {
  return c.nome + " - " + c.preco.toFixed(2) + " EUR";
}

console.log(etiqueta(cartao)); // Teclado - 49.90 EUR

// @ts-expect-error custoInterno não foi escolhido: não existe em CartaoProduto
console.log(cartao.custoInterno);

// @ts-expect-error K extends keyof T rejeita uma chave inexistente em Produto
type Errado = Pick<Produto, "margem">;

type Nivel = "baixo" | "medio" | "alto";

type Pontuacoes = Record<Nivel, number>;

const pontuacoes: Pontuacoes = { baixo: 1, medio: 5, alto: 10 };

function pontuar(nivel: Nivel): number {
  return pontuacoes[nivel];
}

console.log(pontuar("medio")); // 5
console.log(pontuar("alto")); // 10

// @ts-expect-error falta a chave alto: Record com união de literais é exaustivo
const incompletas: Pontuacoes = { baixo: 1, medio: 5 };
console.log(incompletas.baixo); // 1

const aberto: Record<string, number> = { baixo: 1 };
console.log(aberto.inexistente); // undefined, apesar de o tipo prometer number

interface Sessao {
  readonly id: string;
  utilizador: string;
  token: string;
  expiraEm: string;
}

type OmitEstrito<T, K extends keyof T> = Omit<T, K>;

// A chave está mal escrita, mas keyof any aceita-a e nada é removido
type SessaoSegura = Omit<Sessao, "tokn">;

const fuga: SessaoSegura = {
  id: "s1",
  utilizador: "ana",
  token: "abc123",
  expiraEm: "2024-05-01",
