type SessaoPublica = OmitEstrito<Sessao, "token">;

const segura: SessaoPublica = {
  id: "s2",
  utilizador: "rui",
  expiraEm: "2024-05-02",
};
console.log(segura.utilizador); // rui

// @ts-expect-error token foi mesmo removida deste tipo
console.log(segura.token);

// @ts-expect-error o constraint K extends keyof T apanha a chave mal escrita
type Apanhado = OmitEstrito<Sessao, "tokn">;

interface Funcionario {
  readonly id: string;
  nome: string;
  email: string;
  salario: number;
  departamento: "engenharia" | "vendas" | "suporte";
}

type OmitEstrito<T, K extends keyof T> = Omit<T, K>;

type FormularioFuncionario = Pick<Funcionario, "nome" | "email" | "departamento">;
type FuncionarioPublico = OmitEstrito<Funcionario, "salario">;
type PorDepartamento = Record<Funcionario["departamento"], FuncionarioPublico[]>;

function criar(form: FormularioFuncionario, id: string, salario: number): Funcionario {
  return { id, salario, ...form };
}

function publicar(f: Funcionario): FuncionarioPublico {
  const { salario: _, ...resto } = f;
  return resto;
}

function agrupar(lista: Funcionario[]): PorDepartamento {
  const grupos: PorDepartamento = { engenharia: [], vendas: [], suporte: [] };
  for (const f of lista) {
    grupos[f.departamento].push(publicar(f));
  }
  return grupos;
}

const equipa: Funcionario[] = [
  criar({ nome: "Ana", email: "ana@exemplo.pt", departamento: "engenharia" }, "f1", 3000),
  criar({ nome: "Rui", email: "rui@exemplo.pt", departamento: "vendas" }, "f2", 2500),
];

const grupos = agrupar(equipa);
console.log(grupos.engenharia.length); // 1
console.log(grupos.suporte.length); // 0
console.log(grupos.vendas[0].nome); // Rui

// @ts-expect-error o tipo público já não tem salario
console.log(grupos.vendas[0].salario);
